UPDATE duplicate_review_decision
SET is_current = FALSE
WHERE workspace_id = #{workspaceId}
  AND record_type = #{recordType}
  AND kind = #{kind}
  AND evidence_fingerprint = #{evidenceFingerprint}
  AND is_current = TRUE

mapper.insert:
INSERT INTO duplicate_review_decision ( workspace_id, record_type, kind, evidence_fingerprint, low_person_id, high_person_id, low_company_id, high_company_id, evidence_person_identity_id, evidence_company_identity_id, oversized_marker, collision_size, state, is_current, detected_at) WITH requested_groups AS (
SELECT #{group.recordType} AS record_type, #{group.kind} AS kind, #{group.normalizedValue} AS normalized_value, #{group.evidenceFingerprint} AS evidence_fingerprint
), person_members AS ( SELECT requested.kind, requested.evidence_fingerprint, person_identity.id AS identity_id, person_identity.person_id AS record_id, COUNT(*) OVER ( PARTITION BY requested.kind, requested.normalized_value ) AS collision_size, ROW_NUMBER() OVER ( PARTITION BY requested.kind, requested.normalized_value ORDER BY person_identity.person_id, person_identity.id ) AS member_ordinal FROM requested_groups requested JOIN person_identity ON requested.record_type = 'person' AND person_identity.workspace_id = #{workspaceId} AND person_identity.kind = requested.kind AND person_identity.normalized_value = requested.normalized_value AND person_identity.superseded_at IS NULL JOIN identity_collision ON identity_collision.workspace_id = person_identity.workspace_id AND identity_collision.person_identity_id = person_identity.id JOIN person ON person.workspace_id = person_identity.workspace_id AND person.id = person_identity.person_id AND person.archived_at IS NULL AND person.suspended_at IS NULL AND person.provision_ceased_at IS NULL ), company_members AS ( SELECT requested.kind, requested.evidence_fingerprint, company_identity.id AS identity_id, company_identity.company_id AS record_id, COUNT(*) OVER ( PARTITION BY requested.kind, requested.normalized_value ) AS collision_size, ROW_NUMBER() OVER ( PARTITION BY requested.kind, requested.normalized_value ORDER BY company_identity.company_id, company_identity.id ) AS member_ordinal FROM requested_groups requested JOIN company_identity ON requested.record_type = 'company' AND company_identity.workspace_id = #{workspaceId} AND company_identity.kind = requested.kind AND company_identity.normalized_value = requested.normalized_value AND company_identity.superseded_at IS NULL JOIN identity_collision ON identity_collision.workspace_id = company_identity.workspace_id AND identity_collision.company_identity_id = company_identity.id JOIN company ON company.workspace_id = company_identity.workspace_id AND company.id = company_identity.company_id AND company.archived_at IS NULL ), person_pair_members AS ( SELECT * FROM person_members WHERE collision_size BETWEEN 2 AND #{maximumPairGroupSize} AND member_ordinal <= #{maximumPairGroupSize} ), company_pair_members AS ( SELECT * FROM company_members WHERE collision_size BETWEEN 2 AND #{maximumPairGroupSize} AND member_ordinal <= #{maximumPairGroupSize} ) SELECT #{workspaceId}, 'person', low_member.kind, low_member.evidence_fingerprint, low_member.record_id, high_member.record_id, NULL, NULL, low_member.identity_id, NULL, NULL, low_member.collision_size, 'open', TRUE, #{detectedAt} FROM person_pair_members low_member JOIN person_pair_members high_member ON high_member.kind = low_member.kind AND high_member.evidence_fingerprint = low_member.evidence_fingerprint AND high_member.record_id > low_member.record_id UNION ALL SELECT #{workspaceId}, 'person', member.kind, member.evidence_fingerprint, NULL, NULL, NULL, NULL, member.identity_id, NULL, 1, member.collision_size, 'open', TRUE, #{detectedAt} FROM person_members member WHERE member.member_ordinal = 1 AND member.collision_size > #{maximumPairGroupSize} UNION ALL SELECT #{workspaceId}, 'company', low_member.kind, low_member.evidence_fingerprint, NULL, NULL, low_member.record_id, high_member.record_id, NULL, low_member.identity_id, NULL, low_member.collision_size, 'open', TRUE, #{detectedAt} FROM company_pair_members low_member JOIN company_pair_members high_member ON high_member.kind = low_member.kind AND high_member.evidence_fingerprint = low_member.evidence_fingerprint AND high_member.record_id > low_member.record_id UNION ALL SELECT #{workspaceId}, 'company', member.kind, member.evidence_fingerprint, NULL, NULL, NULL, NULL, NULL, member.identity_id, 1, member.collision_size, 'open', TRUE, #{detectedAt} FROM company_members member WHERE member.member_ordinal = 1 AND member.collision_size > #{maximumPairGroupSize} ON DUPLICATE KEY UPDATE evidence_person_identity_id = VALUES(evidence_person_identity_id), evidence_company_identity_id = VALUES(evidence_company_identity_id), collision_size = VALUES(collision_size), is_current = TRUE

