SELECT id
FROM duplicate_review_decision
WHERE workspace_id = #{workspaceId}
  AND record_type = #{recordType}
  AND kind = #{kind}
  AND evidence_fingerprint = #{evidenceFingerprint}
  AND is_current = TRUE
  AND oversized_marker IS NULL
  AND (
    (record_type = 'person'
     AND low_person_id = #{lowRecordId}
     AND high_person_id = #{highRecordId})
    OR
    (record_type = 'company'
     AND low_company_id = #{lowRecordId}
     AND high_company_id = #{highRecordId})
  )
FOR UPDATE

