UPDATE duplicate_review_decision
SET state = 'dismissed',
    dismissed_at = #{decidedAt},
    dismissed_by_user_id = #{actorId},
    dismissal_note = #{note,jdbcType=VARCHAR}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND is_current = TRUE

UPDATE duplicate_review_decision
SET dismissed_by_user_id = NULL
WHERE workspace_id = #{workspaceId}
  AND dismissed_by_user_id = #{userId}

UPDATE duplicate_review_decision
SET dismissed_by_user_id = NULL
WHERE dismissed_by_user_id = #{userId}
